package com.example.kitsune.data.entity

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Representation of a discovered comic folder indexed in the local database.
 * Filesystem remains the single source of truth; this entity indexes metadata and user state.
 *
 * @param id Internal unique identifier generated by Room.
 * @param rootUriString URI string of the storage root under which this comic exists.
 * @param relativePath Relative directory path under the root (e.g. "Comics/One Piece").
 * @param title Display title derived from the comic folder name.
 * @param isBookmarked User bookmark/favorite state.
 * @param lastReadAt Timestamp (epoch millis) when any chapter was last read, nullable.
 * @param coverEntryPath Internal relative image entry path of the cover in Chapter 1.cbz, or null if unavailable.
 * @param lastScannedAt Timestamp when this comic was last reconciled by the scanner.
 */
@Entity(
    tableName = "comics",
    indices = [
        Index(value = ["rootUriString", "relativePath"], unique = true),
        Index(value = ["rootUriString", "title"]),
        Index(value = ["isBookmarked"]),
        Index(value = ["lastReadAt"])
    ]
)
data class ComicEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val rootUriString: String,
    val relativePath: String,
    val title: String,
    val isBookmarked: Boolean = false,
    val lastReadAt: Long? = null,
    val coverEntryPath: String? = null,
    val lastScannedAt: Long = System.currentTimeMillis()
)

